export function getTerritoryRealGeometry(level: string, id: string, codeOrPcode?: string, nom?: string): any {
  if (level === 'quartier') {
    if (TERRITORY_QUARTIER_BOUNDARIES[id]) return TERRITORY_QUARTIER_BOUNDARIES[id];
    const stripped = id.replace(/^qtr-osm-/, 'qtr-');
    if (TERRITORY_QUARTIER_BOUNDARIES[stripped]) return TERRITORY_QUARTIER_BOUNDARIES[stripped];
    const osmPrefixed = id.startsWith('qtr-osm-') ? id : id.replace(/^qtr-/, 'qtr-osm-');
    if (TERRITORY_QUARTIER_BOUNDARIES[osmPrefixed]) return TERRITORY_QUARTIER_BOUNDARIES[osmPrefixed];
    if (codeOrPcode && TERRITORY_QUARTIER_BOUNDARIES[codeOrPcode]) return TERRITORY_QUARTIER_BOUNDARIES[codeOrPcode];
    if (nom) {
      const clean = nom.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, '').trim();
      if (TERRITORY_QUARTIER_BOUNDARIES[clean]) return TERRITORY_QUARTIER_BOUNDARIES[clean];
    }
    return null;
  }
  if (level === 'commune') {
    if (codeOrPcode && TERRITORY_COMMUNE_BOUNDARIES[codeOrPcode]) {
      return TERRITORY_COMMUNE_BOUNDARIES[codeOrPcode];
    }
    if (nom) {
      const clean = nom.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').trim();
      if (TERRITORY_COMMUNE_BOUNDARIES[clean]) {
        return TERRITORY_COMMUNE_BOUNDARIES[clean];
      }
    }
    return null;
  }
  if (level === 'prefecture') {
    if (codeOrPcode && TERRITORY_PREFECTURE_BOUNDARIES[codeOrPcode]) {
      return TERRITORY_PREFECTURE_BOUNDARIES[codeOrPcode];
    }
    if (nom) {
      const clean = nom.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').trim();
      if (TERRITORY_PREFECTURE_BOUNDARIES[clean]) {
        return TERRITORY_PREFECTURE_BOUNDARIES[clean];
      }
    }
    return null;
  }
  if (level === 'region') {
    return TERRITORY_REGION_BOUNDARIES[id] || null;
  }
  return null;
}
